6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      svg circle {
60	        stroke: CanvasText;
61	        stroke-width: 2;
62	      }
63	    }
64	    body {
65	      min-height: 100vh;
66	      min-height: 100dvh;
67	      display: grid;
68	      place-items: center;
69	      padding: 1rem;
70	      background: var(--bg);
71	      color: var(--text);
72	      font-family: system-ui, -apple-system, sans-serif;
73	    }
74	    main {
75	      width: 100%;
76	      display: flex;
77	      flex-direction: column;
78	      align-items: center;
79	      text-align: center;
80	    }
81	    .circle {
82	      display: block;
83	      width: min(360px, 100%, 60vh);
84	      aspect-ratio: 1;
85	      border: 0;
86	      border-radius: 50%;
87	      background: none;
88	      color: var(--fg);
89	      cursor: pointer;
90	      touch-action: manipulation;
91	      -webkit-tap-highlight-color: transparent;
92	      /* Shift+click and double-click would otherwise select the text below */
93	      -webkit-user-select: none;
94	      user-select: none;
95	      transition: color 0.4s ease;
96	      min-height: 48px;
97	      min-width: 48px;
98	    }
99	    .no-transition,
100	    .no-transition svg {
101	      transition: none !important;
102	    }
103	    .circle:focus-visible {
104	      outline: 3px solid currentColor;
105	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
106	      outline-offset: 12px;
107	    }
108	    svg {
109	      display: block;
110	      width: 100%;
111	      height: 100%;
112	      overflow: visible;
113	      opacity: 0.85;
114	      filter: var(--drop);
115	      transition: opacity 0.3s ease;
116	    }
117	    .circle:active svg,
118	    .circle:focus-visible svg {
119	      opacity: 1;
120	    }
121	    @keyframes pulse {
122	      0% {
123	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
124	      }
125	      100% {
126	        filter: var(--drop) drop-shadow(0 0 0 transparent);
127	      }
128	    }
129	    @media (hover: hover) {
130	      .circle:hover svg {
131	        opacity: 1;
132	      }
133	    }
134	    @media (prefers-reduced-motion: no-preference) {
135	      svg {
136	        transition:
137	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
138	          opacity 0.3s ease;
139	      }
140	      .circle:focus-visible svg {
141	        transform: scale(1.05);
142	      }
143	      .circle:active svg {
144	        transform: scale(0.97);
145	      }
146	      .circle.color-changed svg {
147	        animation: pulse 0.5s ease-out;
148	      }
149	    }
150	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
151	      .circle:hover:not(:active) svg {
152	        transform: scale(1.05);
153	      }
154	    }
155	    .visually-hidden {
156	      position: absolute;
157	      width: 1px;
158	      height: 1px;
159	      overflow: hidden;
160	      clip-path: inset(50%);
161	      white-space: nowrap;
162	    }
163	    .status {
164	      margin-top: 2rem;
165	      font-weight: 600;
166	    }
167	    .hint {
168	      margin-top: 0.25rem;
169	      font-size: 0.875rem;
170	      line-height: 1.75;
171	    }
172	    .help-button {
173	      margin-left: 0.5rem;
174	      display: inline-block;
175	      width: 1.5rem;
176	      height: 1.5rem;
177	      border-radius: 50%;
178	      background: var(--kbd-bg);
179	      border: 1px solid var(--text);
180	      color: var(--text);
181	      cursor: pointer;
182	      font: inherit;
183	      font-size: 0.75rem;
184	      font-weight: bold;
185	      line-height: 1;
186	      text-align: center;
187	      vertical-align: middle;
188	      touch-action: manipulation;
189	      transition: background-color 0.2s ease, color 0.2s ease;
190	    }
191	    .help-button:focus-visible {
192	      outline: 2px solid currentColor;
193	      outline-offset: 2px;
194	    }
195	    @media (hover: hover) {
196	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
197	      .help-button:hover {
198	        background: var(--text);
199	        color: var(--bg);
200	      }
201	    }
202	    .keys {
203	      display: none;
204	    }
205	    .keys.visible {
206	      display: inline;
207	    }
208	    @media (hover: none) and (pointer: coarse) {
209	      .hint .keys {
210	        display: none !important;
211	      }
212	      .help-button {
213	        display: none;
214	      }
215	    }
216	    kbd {
217	      display: inline-block;
218	      padding: 0.125rem 0.375rem;
219	      background: var(--kbd-bg);
220	      border: 1px solid transparent;
221	      border-radius: 0.25rem;
222	      font-family: monospace;
223	      font-size: 0.75em;
224	      line-height: 1.2;
225	    }
226	  </style>
227	</head>
228	<body>
229	  <main>
230	    <h1 class="visually-hidden">Animated Circle</h1>
231	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
232	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
233	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
234	      </svg>
235	    </button>
236	    <p class="status" id="status" role="status">Blue</p>
237	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
238	  </main>
239	  <script>
240	    const config = {
241	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
242	      storageKey: 'circle-color',
243	      hapticDuration: 50,
244	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
245	    };
246	
247	    const DOM = {
248	      button: document.querySelector('.circle'),
249	      status: document.querySelector('.status'),
250	      helpButton: document.querySelector('.help-button'),
251	      keyHint: document.querySelector('.keys'),
252	      verbSpan: document.querySelector('.hint .verb'),
253	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
254	    };
255	
256	    const state = {
257	      index: 0,
258	      shiftHeld: false,
259	      hoverCapable: true,
260	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
261	      hoverQuery: matchMedia('(hover: none)'),
262	    };
263	
264	    function loadColor() {
265	      try {
266	        return localStorage.getItem(config.storageKey);
267	      } catch {
268	        return null;
269	      }
270	    }
271	
272	    function saveColor(color) {
273	      try {
274	        localStorage.setItem(config.storageKey, color);
275	      } catch {}
276	    }
277	
278	    function applyColor() {
279	      const color = config.colors[state.index];
280	      DOM.button.dataset.color = color === 'blue' ? '' : color;
281	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
282	    }
283	
284	    function setIndex(next, { haptic = false } = {}) {
285	      if (next === state.index) return;
286	      state.index = next;
287	      applyColor();
288	      saveColor(config.colors[state.index]);
289	
290	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
291	
292	      if (state.reducedMotion.matches) return;
293	      DOM.button.classList.remove('color-changed');
294	      void DOM.button.offsetWidth;
295	      DOM.button.classList.add('color-changed');
296	    }
297	
298	    function changeColor(step) {
299	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
300	    }
301	
302	    function updateDeviceVerbs() {
303	      state.hoverCapable = !state.hoverQuery.matches;
304	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
305	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
306	    }
307	
308	    function toggleKeyHintVisibility() {
309	      const expanded = DOM.keyHint.classList.toggle('visible');
310	      DOM.helpButton.setAttribute('aria-expanded', expanded);
311	    }
312	
313	    function handleKeyDown(event) {
314	      if (event.key === 'Enter' || event.key === ' ') {
315	        if (!event.repeat) state.shiftHeld = event.shiftKey;
316	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
317	        return;
318	      }
319	
320	      if (event.altKey || event.ctrlKey || event.metaKey) return;
321	
322	      if (event.key in config.keySteps) {
323	        event.preventDefault();
324	        changeColor(config.keySteps[event.key]);
325	      } else if (event.key === 'Home') {
326	        event.preventDefault();
327	        setIndex(0, { haptic: true });
328	      } else if (event.key === 'End') {
329	        event.preventDefault();
330	        setIndex(config.colors.length - 1, { haptic: true });
331	      }
332	    }
333	
334	    // Initialize
335	    const savedColor = loadColor();
336	    state.index = config.colors.includes(savedColor) ? config.colors.indexOf(savedColor) : 0;
337	    applyColor();
338	
339	    requestAnimationFrame(() => requestAnimationFrame(() => {
340	      DOM.button.classList.remove('no-transition');
341	    }));
342	
343	    function syncKeyHint() {
344	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
345	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
346	    }
347	
348	    updateDeviceVerbs();
349	    syncKeyHint();
350	    // e.g. a tablet gaining or losing a trackpad/keyboard
351	    state.hoverQuery.addEventListener('change', () => {
352	      updateDeviceVerbs();
353	      syncKeyHint();
354	    });
355	
356	    // Event listeners
357	    DOM.button.addEventListener('keydown', handleKeyDown);
358	    DOM.button.addEventListener('keyup', (event) => {
359	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
360	    });
361	    DOM.button.addEventListener('blur', () => {
362	      state.shiftHeld = false;
363	    });
364	    DOM.button.addEventListener('click', (event) => {
365	      if (event.detail > 1) return;
366	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
367	      state.shiftHeld = false;
368	    });
369	    DOM.button.addEventListener('dblclick', (event) => {
370	      event.preventDefault();
371	      setIndex(0);
372	    });
373	    DOM.button.addEventListener('animationend', () => {
374	      DOM.button.classList.remove('color-changed');
375	    });
376	
377	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
378	
379	    addEventListener('storage', (event) => {
380	      if (event.key !== config.storageKey && event.key !== null) return;
381	      const newIndex = config.colors.indexOf(event.newValue);
382	      state.index = newIndex === -1 ? 0 : newIndex;
383	      applyColor();
384	    });
385	  </script>
386	</body>
387	</html>
